SELECT u.URL, u.ProperName, u.Team_ID FROM dbo.URL_ProperName_Mapping u WHERE (u.URL LIKE '%maxpreps.com/me/%' OR u.URL LIKE '%maxpreps.com/vt/%') AND u.ProperName IN ('Auburn Little (ME)','Dover-Foxcroft (ME)','Mattanawcook (ME)','Kittery Traip (ME)','Belfast Crosby (ME)','Bangor John Bapst (ME)','Fryeburg (ME)','Skowhegan River (ME)','Lincoln Mattanawcook Lee (ME)','Mount Desert Island (ME)','Jericho Mt. Mansfield (VT)','Fairfax Bellows Free (VT)');